G=load(); print(sorted(G))
def solve(I):
    h,w=len(I),len(I[0])
    cnt=C(x for r in I for x in r)
    bg=cnt.most_common(1)[0][0]
    # enclosed bg cells: flood from border
    seen=set(); q=deque()
    for i in range(h):
        for j in (0,w-1):
            if I[i][j]==bg and (i,j) not in seen: seen.add((i,j)); q.append((i,j))
    for j in range(w):
        for i in (0,h-1):
            if I[i][j]==bg and (i,j) not in seen: seen.add((i,j)); q.append((i,j))
    while q:
        i,j=q.popleft()
        for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+dx,j+dy
            if 0<=ni<h and 0<=nj<w and I[ni][nj]==bg and (ni,nj) not in seen:
                seen.add((ni,nj)); q.append((ni,nj))
